with exploded as (select id, service, host, log_ts, latency_ms, status_code, k, v from app_logs lateral view explode(context) x as k, v), valid as (select id, service, host, log_ts, latency_ms, status_code, k, v, round(latency_ms / status_code, 2) as latency_ms_per_status_code, coalesce(k, 'UNKNOWN') as resolved_k from exploded where k is not null and k in ('trace', 'region')), with_prev as (select *, lag(log_ts) over (partition by service order by log_ts, id, k) as prev_log_ts from valid), gaps as (select *, case when prev_log_ts is null or log_ts > prev_log_ts + interval 1 hour then 1 else 0 end as is_new_burst from with_prev), sessionized as (select *, sum(is_new_burst) over (partition by service order by log_ts, id, k rows between unbounded preceding and current row) as session_no from gaps), prev_events as (select *, lag(prev_log_ts) over (partition by k order by prev_log_ts, id, k) as prev_prev_log_ts from sessionized), gaps_2 as (select *, case when prev_prev_log_ts is null or prev_log_ts > prev_prev_log_ts + interval 60 days then 1 else 0 end as is_new_burst_2 from prev_events), islands as (select *, sum(is_new_burst_2) over (partition by k order by prev_log_ts, id, k rows between unbounded preceding and current row) as burst_id from gaps_2), enriched as (select id, service, host, log_ts, latency_ms, status_code, k, v, latency_ms_per_status_code, resolved_k, prev_log_ts, is_new_burst, session_no, prev_prev_log_ts, is_new_burst_2, burst_id, avg(latency_ms) over (partition by service) as service_avg_latency_ms, first_value(latency_ms_per_status_code, true) over (partition by service, host order by prev_log_ts, id, k rows between unbounded preceding and current row) as first_known_latency_ms_per_status_code from islands), latest as (select *, rank() over (partition by k order by latency_ms) as rank_in_group from enriched qualify rank_in_group = 1) select id, service, host, log_ts, latency_ms, status_code, k, v, latency_ms_per_status_code, resolved_k, prev_log_ts, is_new_burst, session_no, prev_prev_log_ts, is_new_burst_2, burst_id, service_avg_latency_ms, first_known_latency_ms_per_status_code, rank_in_group, ntile(4) over (partition by k order by service_avg_latency_ms desc, id, k) as service_avg_latency_ms_bucket, last_value(is_new_burst, true) over (partition by service order by session_no, id, k rows between unbounded preceding and current row) as last_known_is_new_burst from latest;
